def appliquer(tx, sur, lot=None):
    """Remplace dans tx[lang] les champs du registre luxe. lot = None (Aigle Royal) ou dict AU / RE."""
    for l, d in sur.items():
        t = tx[l]
        for k in ("title", "desc", "ital", "hero", "intro", "apres", "web"):
            if k in d:
                t[k] = d[k]
        if "bref" in d:   # Aigle Royal : liste complète, la cuisine casher reste en dernier
            t["bref"] = d["bref"] + [t["bref"][-1]]
        if "faq" in d:
            t["faq"] = d["faq"]
        if "suites" in d:
            t["bref"] = [b if b[0] != "bed-double" else d["suites"] for b in t["bref"]]
        if "service" in d:   # remplace « Ski room » et « Comforts » par une ligne Service
            t["bref"] = [b for b in t["bref"] if b[0] not in ("snowflake", "check")]
            t["bref"].insert(len(t["bref"]) - 1, d["service"])
        if "faq1" in d:
            t["faq"] = [d["faq1"]] + t["faq"][1:]
    return tx
